SELECT 
FROM ecom_payout p


    p.status = #{status}
    AND p.store_id = #{storeId}
    AND COALESCE(p.payout_date, p.expected_date) >= #{begin}
    AND COALESCE(p.payout_date, p.expected_date) <= #{end}

        AND (st.settlement_no LIKE CONCAT('%', #{keyword}, '%') OR p.bank_ref LIKE CONCAT('%', #{keyword}, '%')
             OR p.remark LIKE CONCAT('%', #{keyword}, '%') OR s.name LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY COALESCE(p.payout_date, p.expected_date) DESC, p.id DESC

SELECT 
FROM ecom_payout p

WHERE p.id = #{id}

SELECT p.status AS "status", COUNT(*) AS "cnt", COALESCE(SUM(p.expected_base), 0) AS "expectedBase", COALESCE(SUM(p.amount_base), 0) AS "amountBase" FROM ecom_payout p
p.store_id = #{storeId}
GROUP BY p.status
